mapper.select:
/* PcccMapper.selectPcccList : Pccc List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT A.* , COUNT(A.HBL_NO) OVER() AS TOTAL_COUNT , COUNT(CASE WHEN A.STATUS = '01' THEN A.HBL_NO END) OVER() AS TOTAL_PASS_COUNT , COUNT(CASE WHEN A.STATUS = '03' THEN A.HBL_NO END) OVER() AS STOP_COUNT , COUNT(CASE WHEN A.STATUS = '03' THEN A.HBL_NO END) OVER() AS ERROR_COUNT , COUNT(CASE WHEN (A.STATUS = '04' or A.STATUS = '05' or A.STATUS = '06') and A.PCCC_DATE_TIME IS NOT NULL THEN A.HBL_NO END) OVER() AS TOTAL_COMPLETE FROM ( SELECT cusId.CUSTOMS_ID_JOB_NO AS CUSTOMS_ID_JOB_NO , cusId.ENT_CODE AS ENT_CODE , cusId.REQUEST_ID AS REQUEST_ID , CASE WHEN cusId.INPUT_METHOD = 'COUPANG' THEN 'COUPANG' ELSE 'POST' END AS INPUT_METHOD , CASE WHEN cusId.INPUT_METHOD = 'COUPANG' THEN 'PRE' ELSE 'POST' END AS INPUT_METHOD_EXCEL , cusId.STATUS AS STATUS , CASE WHEN cusId.STATUS = '01' THEN 'X' ELSE '' END AS STATUS_EXCEL , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = cusId.ENT_CODE AND CODE = cusId.STATUS AND GROUP_CODE = 'PCCC_STATUS') AS STATUS_NAME , cusId.CUST_CODE_LV1 AS CUST_CODE_LV1 , (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = cusId.ENT_CODE AND CUSTOMER_CODE = cusId.CUST_CODE_LV1) AS CUST_NAME_LV1 , CONVERT(VARCHAR(10), CONVERT(DATE, cusId.PO_DATE_TIME), 120) AS PO_DATE_TIME , cusId.HBL_NO AS HBL_NO , cusId.PO_NO AS PO_NO , cusId.AUTO_SEND_CNT AS ELAPSE_DATE , ISNULL(alarm.SEND_CNT, 0) AS SEND_CNT , cusId.ORIG_CUSTOMS_ID AS ORIG_CUSTOMS_ID , cusId.ORIG_CONSIGNEE_NAME AS ORIG_CONSIGNEE_NAME , cusId.ORIG_CONSIGNEE_F_NAME AS ORIG_CONSIGNEE_F_NAME , cusId.ORIG_CONSIGNEE_L_NAME AS ORIG_CONSIGNEE_L_NAME , cusId.ORIG_CONSIGNEE_HP AS ORIG_CONSIGNEE_HP , cusId.ORIG_CONSIGNEE_ZIPCODE AS ORIG_CONSIGNEE_ZIPCODE , CONVERT(VARCHAR(16), cusId.COUPANG_SEND_DATE_TIME, 120) AS COUPANG_SEND_DATE_TIME , rst.ERROR_CODE AS ERROR_CODE , rst.ERROR_DESC AS ERROR_DESC , CASE WHEN (cusId.STATUS = '04' or cusId.STATUS = '05' or cusId.STATUS = '06') and cusId.PCCC_DATE_TIME IS NOT NULL THEN CONVERT(VARCHAR(10), CONVERT(DATE, cusId.PCCC_DATE_TIME), 120) ELSE '' END AS PCCC_DATE_TIME , CONVERT(VARCHAR(10), CONVERT(DATE, cusId.OUT_CALL1), 120) AS OUT_CALL1 , CONVERT(VARCHAR(10), CONVERT(DATE, cusId.OUT_CALL2), 120) AS OUT_CALL2 , cusId.OUT_CALL_TYPE AS OUT_CALL_TYPE , alarm.RECENT_SEND_TIME AS RECENT_SEND_TIME , alarm.SEND_TIME_1 AS SEND_TIME_1 , alarm.SEND_TIME_2 AS SEND_TIME_2 , alarm.SEND_TIME_3 AS SEND_TIME_3 , alarm.SEND_TIME_4 AS SEND_TIME_4 , alarm.SEND_TIME_5 AS SEND_TIME_5 , (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CB_CODE) AS CB_CODE , (SELECT TEL FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CB_CODE) AS CB_TEL , (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) AS CUST_NAME_LV2 , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = cusId.ENT_CODE AND CODE = cusId.OUT_CALL_TYPE AND GROUP_CODE = 'PCCC_OUT_CALL_TYPE') AS OUT_CALL_TYPE_NAME , cusId.REGISTER_USER_ID AS REGISTER_USER_ID , CONVERT(VARCHAR(10), CONVERT(DATE, cusId.REGISTER_DATE_TIME), 120) AS REGISTER_DATE_TIME , cusId.UPDATE_USER_ID AS UPDATE_USER_ID , cusId.UPDATE_DATE_TIME AS UPDATE_DATE_TIME FROM TB_ECM_CUSTOMS_ID_INFO cusId LEFT JOIN TB_ECM_CUSTOMS_ID_INFO_RESULT rst ON rst.TB_ECM_CUSTOMS_ID_INFO = cusId.CUSTOMS_ID_JOB_NO AND rst.REGISTER_DATE_TIME = ( SELECT MAX(REGISTER_DATE_TIME) FROM TB_ECM_CUSTOMS_ID_INFO_RESULT sub WHERE sub.TB_ECM_CUSTOMS_ID_INFO = cusId.CUSTOMS_ID_JOB_NO) LEFT JOIN ( SELECT REF_JOB_NO , COUNT(*) AS SEND_CNT , MAX(CASE WHEN RN_DESC = 1 THEN CONVERT(VARCHAR(19), SEND_DATE_TIME, 120) END) AS RECENT_SEND_TIME , MAX(CASE WHEN RN_ASC = 1 THEN CONVERT(VARCHAR(19), SEND_DATE_TIME, 120) END) AS SEND_TIME_1 , MAX(CASE WHEN RN_ASC = 2 THEN CONVERT(VARCHAR(19), SEND_DATE_TIME, 120) END) AS SEND_TIME_2 , MAX(CASE WHEN RN_ASC = 3 THEN CONVERT(VARCHAR(19), SEND_DATE_TIME, 120) END) AS SEND_TIME_3 , MAX(CASE WHEN RN_ASC = 4 THEN CONVERT(VARCHAR(19), SEND_DATE_TIME, 120) END) AS SEND_TIME_4 , MAX(CASE WHEN RN_ASC = 5 THEN CONVERT(VARCHAR(19), SEND_DATE_TIME, 120) END) AS SEND_TIME_5 FROM ( SELECT REF_JOB_NO, SEND_DATE_TIME, ROW_NUMBER() OVER(PARTITION BY REF_JOB_NO ORDER BY SEND_DATE_TIME ASC) AS RN_ASC, ROW_NUMBER() OVER(PARTITION BY REF_JOB_NO ORDER BY SEND_DATE_TIME DESC) AS RN_DESC FROM TB_SMS_ALARM ) ranked GROUP BY REF_JOB_NO ) alarm ON alarm.REF_JOB_NO = cusId.CUSTOMS_ID_JOB_NO LEFT JOIN TB_ECM_OD od ON od.OD_JOB_NO = cusId.CUSTOMS_ID_JOB_NO WHERE 1=1 -- AND cusId.VERIFY_RESULT = 'E'
AND (cusId.INPUT_METHOD = 'COUPANG' OR cusId.INPUT_METHOD = 'CPO') AND cusId.AUTO_SEND_CNT >= '2'
AND cusId.INPUT_METHOD = 'COUPANG'
AND cusId.INPUT_METHOD != 'COUPANG'
AND cusId.status IN (#{item})
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')
AND ${srchCusType} = #{srchCuslv1}
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND cusId.CUSTOMS_ID_JOB_NO IN (#{item})
)A

/* PcccMapper.selectPcccDetail : Pccc Detail */ SELECT cusId.CUSTOMS_ID_JOB_NO AS CUSTOMS_ID_JOB_NO , cusId.ENT_CODE AS ENT_CODE , cusId.REQUEST_ID AS REQUEST_ID , cusId.INPUT_METHOD AS INPUT_METHOD , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = cusId.ENT_CODE AND CODE = cusId.STATUS AND GROUP_CODE = 'PCCC_STATUS') AS STATUS_NAME , cusId.HBL_NO AS HBL_NO , cusId.PO_NO AS PO_NO , CONVERT(VARCHAR(10), CONVERT(DATE, cusId.PO_DATE_TIME), 120) AS PO_DATE_TIME ,(SELECT COUNT(REF_JOB_NO) FROM TB_SMS_ALARM WHERE REF_JOB_NO = cusId.CUSTOMS_ID_JOB_NO) AS SEND_CNT , cusId.AUTO_SEND_CNT AS ELAPSE_DATE , CONVERT(VARCHAR(16), cusId.PCCC_DATE_TIME, 120) AS PCCC_DATE_TIME , cusId.ORIG_CUSTOMS_ID AS ORIG_CUSTOMS_ID , cusId.ORIG_CONSIGNEE_NAME AS ORIG_CONSIGNEE_NAME , cusId.ORIG_CONSIGNEE_F_NAME AS ORIG_CONSIGNEE_F_NAME , cusId.ORIG_CONSIGNEE_L_NAME AS ORIG_CONSIGNEE_L_NAME , cusId.ORIG_CONSIGNEE_HP AS ORIG_CONSIGNEE_HP , cusId.ORIG_CONSIGNEE_ZIPCODE AS ORIG_CONSIGNEE_ZIPCODE , cusId.AFTER_CUSTOMS_ID AS AFTER_CUSTOMS_ID , cusId.AFTER_CONSIGNEE_NAME AS AFTER_CONSIGNEE_NAME , cusId.AFTER_CONSIGNEE_F_NAME AS AFTER_CONSIGNEE_F_NAME , cusId.AFTER_CONSIGNEE_L_NAME AS AFTER_CONSIGNEE_L_NAME , cusId.AFTER_CONSIGNEE_HP AS AFTER_CONSIGNEE_HP , cusId.AFTER_CONSIGNEE_ZIPCODE AS AFTER_CONSIGNEE_ZIPCODE , CONVERT(VARCHAR(16), cusId.COUPANG_SEND_DATE_TIME, 120) AS COUPANG_SEND_DATE_TIME , CONVERT(VARCHAR(16), cusId.OUT_CALL1, 120) AS OUT_CALL1 , CONVERT(VARCHAR(16), cusId.OUT_CALL2, 120) AS OUT_CALL2 , (SELECT MAX(CONVERT(VARCHAR(16), SEND_DATE_TIME, 120)) FROM TB_SMS_ALARM WHERE ENT_CODE = cusId.ENT_CODE AND REF_JOB_NO = cusId.CUSTOMS_ID_JOB_NO) AS RECENT_SEND_TIME , cusId.OUT_CALL_TYPE AS OUT_CALL_TYPE , cusId.REGISTER_DATE_TIME AS REGISTER_DATE_TIME , rst.ERROR_CODE AS ERROR_CODE FROM TB_ECM_CUSTOMS_ID_INFO cusId LEFT JOIN TB_ECM_CUSTOMS_ID_INFO_RESULT rst ON rst.TB_ECM_CUSTOMS_ID_INFO = cusId.CUSTOMS_ID_JOB_NO WHERE 1=1 -- AND cusId.VERIFY_RESULT = 'E'
AND cusId.ENT_CODE = #{srchEntCode}
AND cusId.CUSTOMS_ID_JOB_NO = #{odJobNo}
AND cusId.HBL_NO = #{srchNo}

/* PcccMapper.selectUnipassCustomsVerifyKey : 관세청 개인통관고유부호 인증키 조회 */
SELECT UNIPASS_CUSTOMS_VERIFY_KEY
FROM exps_master.dbo.TB_SMS_ENTERPRISE 
WHERE ENT_CODE = #{entCode}

