/* PcccMapper.updatePccc : PCCC정보 업데이트 */
UPDATE TB_ECM_CUSTOMS_ID_INFO SET
		UPDATE_USER_ID = #{updateUserId}
	   ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	   ,AFTER_CUSTOMS_ID = #{customsId}
	   ,AFTER_CONSIGNEE_NAME  = #{consigneeName}
	   ,AFTER_CONSIGNEE_HP = #{consigneeHp}
	   ,PCCC_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())

	   ,AFTER_CONSIGNEE_ZIPCODE = #{zipCode}


	   ,AFTER_CONSIGNEE_F_NAME = #{consigneeFName}


	   ,AFTER_CONSIGNEE_L_NAME = #{consigneeLName}

	   ,STATUS = #{status}
WHERE
	ENT_CODE = #{entCode}
	AND CUSTOMS_ID_JOB_NO = #{odJobNo}

/* PcccMapper.updateAlarmSendStop : PCCC 알람톡 발송금지 */ UPDATE TB_ECM_CUSTOMS_ID_INFO SET UPDATE_USER_ID = #{userId} ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE()) ,STATUS = CASE WHEN STATUS = '03' THEN NULL ELSE '03' END WHERE
(CUSTOMS_ID_JOB_NO = #{item.customsIdJobNo} AND ENT_CODE = #{item.entCode})
AND (STATUS NOT IN ('01','04','05','06') OR STATUS IS NULL)

