/* PcccMapper.selectPcccBatchList : Pccc Batch List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT A.* FROM ( SELECT smsPc.PCCC_SET_JOB_NO AS PCCC_SET_JOB_NO , smsPc.ENT_CODE AS ENT_CODE , smsPc.CUST_CODE_LV1 AS CUST_CODE_LV1 , cust.CUSTOMER_NAME AS CUST_CODE_LV1_NAME , smsPc.REPEAT_COUNT AS REPEAT_COUNT , smsPc.SEND_TIME_TYPE AS SEND_TIME_TYPE , smsPc.SEND_TIME AS SEND_TIME , CONCAT(CASE WHEN ISNULL(smsPc.SEND_TIME_TYPE, '') = 'AM' THEN '오전' ELSE '오후' END, ' ',ISNULL(smsPc.SEND_TIME, ''),'시') AS SEND_TIME_CONVERT , smsPc.REGISTER_USER_ID AS REGISTER_USER_ID , smsPc.REGISTER_DATE_TIME AS REGISTER_DATE_TIME , smsPc.UPDATE_USER_ID AS UPDATE_USER_ID , smsPc.UPDATE_DATE_TIME AS UPDATE_DATE_TIME FROM TB_SMS_PCCC_SET_INFO smsPc LEFT JOIN TB_SMS_CUSTOMER cust ON cust.CUSTOMER_CODE = smsPc.CUST_CODE_LV1 AND cust.ENT_CODE = smsPc.ENT_CODE WHERE 1=1
AND smsPc.ENT_CODE = #{srchEntCode}
)A

/* PcccMapper.selectPcccBatch : Pccc Batch */ SELECT smsPc.PCCC_SET_JOB_NO AS PCCC_SET_JOB_NO , smsPc.ENT_CODE AS ENT_CODE , smsPc.CUST_CODE_LV1 AS CUST_CODE_LV1 , cust.CUSTOMER_NAME AS CUST_CODE_LV1_NAME , smsPc.REPEAT_COUNT AS REPEAT_COUNT , smsPc.SEND_TIME_TYPE AS SEND_TIME_TYPE , smsPc.SEND_TIME AS SEND_TIME , CONCAT(CASE WHEN ISNULL(smsPc.SEND_TIME_TYPE, '') = 'AM' THEN '오전' ELSE '오후' END, ' ',ISNULL(smsPc.SEND_TIME, ''),'시') AS SEND_TIME_CONVERT , smsPc.REGISTER_USER_ID AS REGISTER_USER_ID , smsPc.REGISTER_DATE_TIME AS REGISTER_DATE_TIME , smsPc.UPDATE_USER_ID AS UPDATE_USER_ID , smsPc.UPDATE_DATE_TIME AS UPDATE_DATE_TIME FROM TB_SMS_PCCC_SET_INFO smsPc LEFT JOIN TB_SMS_CUSTOMER cust ON cust.CUSTOMER_CODE = smsPc.CUST_CODE_LV1 AND cust.ENT_CODE = smsPc.ENT_CODE WHERE 1=1
AND smsPc.ENT_CODE = #{entCode}
AND smsPc.CUST_CODE_LV1 = #{custCodeLv1}

/* PcccMapper.selectAlarm : 알림톡 조회 */ SELECT alarm.JOB_TYPE ,alarm.SEQ_NO_ID ,(SELECT LABEL_NAME FROM TB_MMS_MANAGEMENT WHERE TEMPLATE_TYPE = alarm.JOB_TYPE AND TEMPLATE_CODE = alarm.JOB_CODE) AS JOB_TYPE_NAME ,alarm.ALARM_ATTN_ID ,CONVERT(VARCHAR(16), alarm.SEND_DATE_TIME, 120) AS SEND_DATE_TIME ,alarm.BEFORE_VALUE ,alarm.AFTER_VALUE ,CONVERT(VARCHAR(16), DATEADD(hh, -9, alarm.RECV_DATE_TIME), 120) AS RECV_DATE_TIME ,rst.ERROR_DESC AS ERROR_DESC FROM TB_SMS_ALARM alarm LEFT JOIN TB_ECM_CUSTOMS_ID_INFO_RESULT rst ON rst.TB_ECM_CUSTOMS_ID_INFO = alarm.REF_JOB_NO AND rst.SEQ_NO_ID = alarm.SEQ_NO_ID LEFT JOIN TB_ECM_CUSTOMS_ID_INFO cusId ON cusId.CUSTOMS_ID_JOB_NO = alarm.REF_JOB_NO WHERE 1=1
AND alarm.ENT_CODE = #{srchEntCode}
AND alarm.REF_JOB_NO = #{odJobNo}
AND cusId.PO_NO = #{srchNo}
AND (cusId.HBL_NO = #{srchNo} OR cusId.PO_NO = #{srchNo})
AND cusId.HBL_NO = #{srchNo}
ORDER BY alarm.REGISTER_DATE_TIME DESC

