		  ,#{repeatCount}
		  ,#{sendTimeType}
		  ,#{sendTime}
		  ,#{registerUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{registerUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())		
	)

