/* PcccMapper.updatePcccBatch : PCCC 알림톡 설정 수정  */
UPDATE TB_SMS_PCCC_SET_INFO SET
		UPDATE_USER_ID = #{updateUserId}
	   ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())

	   ,REPEAT_COUNT = #{repeatCount}


	   ,SEND_TIME_TYPE = #{sendTimeType}


	   ,SEND_TIME = #{sendTime}

WHERE
 PCCC_SET_JOB_NO = #{pcccSetJobNo}
 AND ENT_CODE = #{entCode}
 AND CUST_CODE_LV1 = #{custCodeLv1}

