/* pcccMapper.insertKakaoSendResultBatch : 카카오톡배치 데이터 저장 */
INSERT INTO TB_SMS_ALARM(
	   SEQ_NO_ID
	  ,ENT_CODE
	  ,ENT_BUSINESS_CODE
	  ,SOLUTION
	  ,REF_JOB_NO
	  ,JOB_TYPE
	  ,JOB_CODE
	  ,MSG_KEY

	  ,ALARM_ATTN_ID

	  ,ALARM_ATTN_HP
	  ,SEND_DATE_TIME
	  ,BEFORE_VALUE
	  ,STATUS
	  ,RESULT_TYPE
	  ,RESULT_LOG
	  ,REGISTER_USER_ID
	  ,REGISTER_DATE_TIME
	  ,UPDATE_USER_ID
	  ,UPDATE_DATE_TIME
)VALUES(
	   #{seqNoId}
	  ,#{entCode}
	  ,#{entBusinessCode}
	  ,#{solution}
	  ,#{customsIdJobNo}
	  ,#{templateType}
	  ,#{templateCode}
	  ,#{msgKey}

	  ,#{attnKey}

	  ,#{dstAddrKey}
	  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	  ,#{beforeValue}
	  ,CASE ISNULL(#{msgKey}, '') WHEN '' THEN 'E' ELSE 'R' END
	  ,CASE ISNULL(#{msgKey}, '') WHEN '' THEN 'E' ELSE NULL END
	  ,CASE ISNULL(#{msgKey}, '') WHEN '' THEN ISNULL(#{returnMessageDetail}, '') ELSE NULL END
	  ,#{updateUserId}
	  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	  ,#{updateUserId}
	  ,DATEADD(HOUR, ${gmtTime}, GETDATE())  
)

mapper.select:
/* PcccMapper.selectPodDetail : POD Detail */ SELECT TOP 1 od.OD_JOB_NO AS OD_JOB_NO , od.ENT_CODE AS ENT_CODE , od.HBL_NO AS HBL_NO , od.DELIVERY_CODE AS DELIVERY_CODE , od.MBL_NO AS MBL_NO , od.MRN AS MRN , od.PO_NO AS PO_NO , od.PO_DATE AS PO_DATE , CONCAT(od.BOUND,', ',od.ORIG_NAME,' - ',od.DEST_NAME) AS ORIG_DEST , od.ORIG_NAME AS ORIG_NAME , od.DEST_NAME AS DEST_NAME , od.CUST_CODE_LV1 AS CUST_CODE_LV1 , CONCAT(OD.CUST_CODE_LV1, '(', (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1), ')') AS CUST_CODE_LV1_NM , od.COMMODITY_ITEM AS COMMODITY_ITEM , od.DELIVERY_NOTE AS DELIVERY_NOTE , od.VESSEL_FLIGHT AS VESSEL_FLIGHT , CONCAT(od.OB_DATE, ' / ' , od.OB_TIME) AS OB_DATE , CONCAT(od.AR_DATE, ' / ' , od.AR_TIME) AS AR_DATE , CONCAT(RIGHT(od.CONSIGNEE_NAME,1),'**') AS ORIG_CONSIGNEE_NAME
, CASE WHEN (SELECT TOP 1 re.OD_JOB_NO FROM TB_ECM_OD_RESEND_INFO re WHERE re.OD_JOB_NO = od.OD_JOB_NO) IS NOT NULL THEN ISNULL(od.RETURN_YN, 'N') ELSE '' END RETURN_YN , CASE WHEN (SELECT TOP 1 mt.OD_JOB_NO FROM TB_ECM_OD_MULTI mt WHERE mt.OD_JOB_NO = od.OD_JOB_NO) IS NOT NULL THEN 'Y' ELSE '' END MULTI_YN , ad.LAST_POD_STATUS
,ad.CUSTOMS_ID_VERIFY ,ad.CUSTOMS_ID_ERROR AS PCCC_YN , (SELECT TOP 1 ERROR_DESC FROM TB_ECM_CUSTOMS_ID_INFO_RESULT WHERE TB_ECM_CUSTOMS_ID_INFO = cusId.CUSTOMS_ID_JOB_NO ORDER BY REGISTER_DATE_TIME DESC) AS ERROR_DESC , (SELECT TOP 1 POD_STATUS FROM TB_ECM_POD_01 WHERE OD_JOB_NO = od.MASTER_OD_JOB_NO AND POD_STATUS = 'ECM070') AS POD_STATUS , ISNULL((SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'STATUS_ORDER_CARGO' AND CODE IN (SELECT TOP 1 POD_STATUS FROM TB_ECM_POD_01 WHERE OD_JOB_NO = od.MASTER_OD_JOB_NO AND POD_STATUS = 'ECM070')),'') AS POD_STATUS_NM , CASE WHEN ad.DROP_YN = 'Y' THEN CONCAT('취하 : ',(SELECT CONCAT(CODE, '.', NAME_${userLanguage}) FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'DROP_CODE' AND CODE = ad.DROP_CODE)) WHEN ad.XRAY_YN = 'Y' THEN CONCAT('X-RAY : ',(SELECT CONCAT(CODE, '.', NAME_${userLanguage}) FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'SE_INSPECTION_CODE' AND CODE = ad.INSPECTION_APP_CODE)) WHEN od.INSPECTION_YN = 'Y' THEN CONCAT('검사 : ',(SELECT CONCAT(CODE, '.', NAME_${userLanguage}) FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'SE_INSPECTION_CODE' AND CODE = ad.SE_INSPECTION_CODE)) WHEN ad.SE_INSPECTION_YN = 'Y' THEN CONCAT('선별 : ',(SELECT CONCAT(CODE, '.', NAME_${userLanguage}) FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'SE_INSPECTION_CODE' AND CODE = ad.SE_INSPECTION_CODE)) ELSE '' END AS POD_REASON , od.CB_CODE , ISNULL(cu.CUSTOMER_NAME, '') AS CB_NAME , ISNULL(cu.TEL, '') AS CB_TEL , od.SHIPPER_NAME , od.ORIG_COUNTRY FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON od.OD_JOB_NO = ad.OD_JOB_NO LEFT JOIN TB_ECM_CUSTOMS_ID_INFO cusId ON cusId.HBL_NO = od.HBL_NO LEFT JOIN TB_SMS_CUSTOMER cu ON cu.ent_code = od.ent_code AND cu.CUSTOMER_CODE = od.CB_CODE AND cu.CUSTOMER_TYPE = 'BR' WHERE 1=1
AND od.ENT_CODE = #{srchEntCode}
AND od.OD_JOB_NO = #{odJobNo}
AND (od.HBL_NO = #{srchNo} OR od.PO_NO = #{srchNo})
AND ${srchNoType} = #{srchNo}
AND od.BOUND_TYPE = #{boundType}

mapper.update:
/* PcccMapper.updateOrderLastPodStatus */
UPDATE ad SET
ad.OD_JOB_NO = ad.OD_JOB_NO

	,ad.DELIVERY_RECV_DATE = #{deliveryRecvDate}




			,ad.LAST_POD_STATUS = LAST_POD_STATUS


			,ad.LAST_POD_STATUS = #{saveStatus}













		FROM TB_ECM_OD od
		INNER JOIN TB_ECM_OD_ADDITIONAL ad
		ON ad.OD_JOB_NO = od.OD_JOB_NO


				WHERE od.MASTER_OD_JOB_NO = #{MASTER_OD_JOB_NO}


				WHERE od.MASTER_OD_JOB_NO IN (

					#{item}

				)




		FROM TB_ECM_OD_ADDITIONAL ad


				WHERE ad.OD_JOB_NO = #{odJobNo}


				WHERE ad.OD_JOB_NO IN (

					#{item}

				)










	AND ISNULL(ad.LAST_POD_STATUS, '') < #{saveStatus}

/** OdMapper.updateOrderDeliveryInfo */
UPDATE TB_ECM_OD_ADDITIONAL SET
OD_JOB_NO = OD_JOB_NO

	,DELIVERY_STATUS = #{saveStatus}


	,DELIVERY_DATE = #{deliveryDate}
	,DELIVERY_YN = 'Y'

WHERE OD_JOB_NO = #{odJobNo}

	AND ISNULL(DELIVERY_STATUS,'') < #{saveStatus}

mapper.delete:
/* PcccMapper.batchTrackingDeletePod : 전자상거래 Order POD 삭제 */
DELETE FROM ${podTableName}


		WHERE POD_STATUS IN (#{item} )
		AND OD_JOB_NO = #{odjobno}


		WHERE POD_STATUS IN (#{item} )
		AND OD_JOB_NO = #{odjobno}


